import { useCart } from './CartContext.js'
import { formatMoney, useCurrency } from './CurrencyContext.js'

const TAX_RATE = 0.1

export default function Cart() {
  const { items, remove, setQuantity } = useCart()
  const currency = useCurrency()

  const subtotal = items.reduce((sum, item) => sum + item.price * item.quantity, 0)
  const tax = subtotal * TAX_RATE
  const total = subtotal + tax

  return (
    <section>
      <h2>Cart</h2>
      {items.length === 0 ? (
        <p>Your cart is empty</p>
      ) : (
        <ul>
          {items.map((item) => (
            <li key={item.id}>
              <span>{item.name}</span>{' '}
              <input
                type="number"
                min="1"
                aria-label={`Quantity for ${item.name}`}
                value={item.quantity}
                onChange={(event) => setQuantity(item.id, event.target.value)}
              />{' '}
              <span>{formatMoney(item.price * item.quantity, currency)}</span>{' '}
              <button type="button" onClick={() => remove(item.id)}>
                Remove
              </button>
            </li>
          ))}
        </ul>
      )}
      <p>Subtotal: {formatMoney(subtotal, currency)}</p>
      <p>Tax (10%): {formatMoney(tax, currency)}</p>
      <p>Total: {formatMoney(total, currency)}</p>
    </section>
  )
}

import { createContext, use } from 'react'

export const CartContext = createContext(null)

export const initialCart = []

export function cartReducer(items, action) {
  switch (action.type) {
    case 'add': {
      const existing = items.find((item) => item.id === action.product.id)
      if (existing) {
        return items.map((item) =>
          item.id === action.product.id ? { ...item, quantity: item.quantity + 1 } : item
        )
      }
      return [...items, { ...action.product, quantity: 1 }]
    }
    case 'remove':
      return items.filter((item) => item.id !== action.id)
    case 'setQuantity': {
      const quantity = Math.max(1, Math.floor(Number(action.quantity)) || 1)
      return items.map((item) => (item.id === action.id ? { ...item, quantity } : item))
    }
    case 'clear':
      return []
    default:
      throw new Error(`Unknown action: ${action.type}`)
  }
}

export function useCart() {
  const cart = use(CartContext)
  if (!cart) throw new Error('useCart must be used within a CartProvider')
  return cart
}

import { useReducer } from 'react'
import { CartContext, cartReducer, initialCart } from './CartContext.js'

export default function CartProvider({ children }) {
  const [items, dispatch] = useReducer(cartReducer, initialCart)

  const value = {
    items,
    count: items.reduce((sum, item) => sum + item.quantity, 0),
    add: (product) => dispatch({ type: 'add', product }),
    remove: (id) => dispatch({ type: 'remove', id }),
    setQuantity: (id, quantity) => dispatch({ type: 'setQuantity', id, quantity }),
    clear: () => dispatch({ type: 'clear' }),
  }

  return <CartContext value={value}>{children}</CartContext>
}

import { useState } from 'react'
import { useCart } from './CartContext.js'

export default function CheckoutForm({ onSubmitted }) {
  const { clear } = useCart()
  const [name, setName] = useState('')
  const [email, setEmail] = useState('')

  const nameError = name.trim() ? '' : 'Name is required'
  const emailError = email.includes('@') ? '' : 'Email must contain @'
  const isValid = !nameError && !emailError

  function handleSubmit(event) {
    event.preventDefault()
    if (!isValid) return
    clear()
    onSubmitted()
  }

  return (
    <form onSubmit={handleSubmit} noValidate>
      <label>
        Name
        <input value={name} onChange={(event) => setName(event.target.value)} />
      </label>
      {nameError && <p role="alert">{nameError}</p>}
      <label>
        Email
        <input type="email" value={email} onChange={(event) => setEmail(event.target.value)} />
      </label>
      {emailError && <p role="alert">{emailError}</p>}
      <button type="submit" disabled={!isValid}>
        Place order
      </button>
    </form>
  )
}

import { createContext, use } from 'react'

export const CurrencyContext = createContext('USD')

export function useCurrency() {
  return use(CurrencyContext)
}

export function formatMoney(amount, currency) {
  return new Intl.NumberFormat('en-US', { style: 'currency', currency }).format(amount)
}

import { useCart } from './CartContext.js'

export default function Header({ onCheckout }) {
  const { count } = useCart()

  return (
    <header>
      <h1>Shop</h1>
      <span>Cart: {count} {count === 1 ? 'item' : 'items'}</span>
      <button type="button" onClick={onCheckout}>
        Checkout
      </button>
    </header>
  )
}

import { useEffect, useEffectEvent } from 'react'

export default function Modal({ title, onClose, children }) {
  const handleKeyDown = useEffectEvent((event) => {
    if (event.key === 'Escape') onClose()
  })

  useEffect(() => {
    const listener = (event) => handleKeyDown(event)
    window.addEventListener('keydown', listener)
    return () => window.removeEventListener('keydown', listener)
  }, [])

  return (
    <div role="dialog" aria-modal="true" aria-label={title}>
      {title && <h2>{title}</h2>}
      <button type="button" aria-label="Close" onClick={onClose}>
        Close
      </button>
      {children}
    </div>
  )
}

import { formatMoney, useCurrency } from './CurrencyContext.js'

export default function ProductItem({ product, onAdd }) {
  const currency = useCurrency()

  return (
    <li>
      <span>{product.name}</span> <span>{formatMoney(product.price, currency)}</span>{' '}
      <button type="button" onClick={() => onAdd(product)}>
        Add
      </button>
    </li>
  )
}

import { useState } from 'react'
import { useCart } from './CartContext.js'
import SearchBox from './SearchBox.jsx'
import ProductItem from './ProductItem.jsx'

export default function ProductList({ products }) {
  const { add } = useCart()
  const [query, setQuery] = useState('')
  const [category, setCategory] = useState('all')

  const categories = [...new Set(products.map((product) => product.category))]
  const normalizedQuery = query.trim().toLowerCase()
  const visible = products.filter(
    (product) =>
      (category === 'all' || product.category === category) &&
      product.name.toLowerCase().includes(normalizedQuery)
  )

  return (
    <section>
      <h2>Products</h2>
      <SearchBox onSearch={setQuery} />
      <select
        aria-label="Category"
        value={category}
        onChange={(event) => setCategory(event.target.value)}
      >
        <option value="all">All categories</option>
        {categories.map((name) => (
          <option key={name} value={name}>
            {name}
          </option>
        ))}
      </select>
      {visible.length === 0 ? (
        <p>No products</p>
      ) : (
        <ul>
          {visible.map((product) => (
            <ProductItem key={product.id} product={product} onAdd={add} />
          ))}
        </ul>
      )}
    </section>
  )
}

import { useEffect, useRef, useState } from 'react'

export default function SearchBox({ onSearch, delay = 300 }) {
  const [text, setText] = useState('')
  const timerRef = useRef(null)

  useEffect(() => () => clearTimeout(timerRef.current), [])

  function handleChange(event) {
    const value = event.target.value
    setText(value)
    clearTimeout(timerRef.current)
    timerRef.current = setTimeout(() => onSearch(value), delay)
  }

  return (
    <input
      type="search"
      placeholder="Search products"
      aria-label="Search products"
      value={text}
      onChange={handleChange}
    />
  )
}
